function finalStudyUnit(title, pages, concepts, example, recall) {
  const [exampleTitle, paragraphs, reason] = example;
  return {
    title, pages,
    sections: [['시험 전 핵심 정리', concepts]],
    readings: [{ title: exampleTitle, source: '개념 적용 예시', paragraphs, reason }],
    recall
  };
}

